"use strict";const userId=parseInt(Id);const userRole=role;const whose=partyVerification(userRole);const server='ws://127.0.0.1:8080';let flagSecondMessageDialog=false;let socket;let lastSN=[];let notifier;let heartbeatInterval;sessionStorage.setItem('isPageReload','false');window.addEventListener('beforeunload',function(event){sessionStorage.setItem('isPageReload','true');});openConnection(server);let notifierDisconnect;function openConnection(server){if(socket){socket.close();socket=null;}
socket=new WebSocket(server);socket.onopen=function(event){if(socket.readyState===WebSocket.OPEN){try{socket.send('idUser::: '+userId);inicializationWebsocket(socket);if(typeof where!=='undefined'){reloadDataForWindow(where,lastSN);}}catch(error){socket=null;console.error('Ошибка отправки сообщения:',error);}}};socket.onerror=function(error){console.error('WebSocket error:',error);closeConnection(socket);};socket.onclose=function(){const isReload=sessionStorage.getItem('isPageReload');if(isReload==='false'){let now=new Date();console.warn('Соединение закрыто. Попытка переподключения через 1 секунду.'+now);startHeartbeat(server);}};}
function closeConnection(socket){if(heartbeatInterval){clearInterval(heartbeatInterval);}
if(socket){socket.close();socket=null;}}
function reloadDataForWindow(where,lastSN){let newWhere=choseWhereForWindow(where);let nameProperty=newWhere+'SN';if(lastSN[nameProperty]!==undefined){invokeDataForWindow(where,lastSN[nameProperty]);}}
function startHeartbeat(server){if(!notifierDisconnect){notifierDisconnect=notifierDisconnect?notifierDisconnect:createNotifier('Произошёл разрыв соединения с сервером!','Подождите пару секунд, мы пытаемся переподключить Вас!');document.body.appendChild(notifierDisconnect);}
let notifierConnect=createNotifier('Мы восстановили соединение с сервером!','Вы можете продолжить с того мееста где остановились!');heartbeatInterval=setInterval(()=>{if(!socket||socket.readyState!==WebSocket.OPEN){console.log('Попытка подключения...');openConnection(server);}else{notifierDisconnect.remove();notifierDisconnect=null;document.body.appendChild(notifierConnect);setInterval(()=>{notifierConnect.remove();},2000);clearInterval(heartbeatInterval);}},1000);}
function createNotifier(title,body,button=null){let shadeBoxNotification=createTagHtml('div','shade-full-screen-box');let blockDisconnectNotification=createTagHtml('div','box-denied-notification');let titleDisconnectNotification=createTagHtml('h4','title-denied',title);let textDisconnectNotification=createTagHtml('p','text-denied-notification',body);let buttonClose=button?createTagHtml('button','close-denied-notification',button):'';massAppendChild(blockDisconnectNotification,titleDisconnectNotification,textDisconnectNotification);if(buttonClose){blockDisconnectNotification.appendChild(buttonClose);buttonClose.addEventListener('click',()=>{shadeBoxNotification.remove();});}
shadeBoxNotification.appendChild(blockDisconnectNotification);return shadeBoxNotification;}
function handlerRequestFromServer(caseTitle,data,user){const functionName='handler'+toCapsCase(caseTitle);if(typeof window[functionName]==='function'){const jsonData=JSON.parse(data);window[functionName](jsonData,user);}else{}}
function inicializationWebsocket(socket){let user;const setUser=(newUser)=>{user=null;user=newUser;};socket.onmessage=function(event){const splitData=event.data.split('::: ');const caseTitle=splitData[0];if(caseTitle==='paramForClient'){handlerParamForClient(splitData[1],setUser);handlerParamForClientPages(user);}else if(caseTitle==='Notification'){handlerNotification(splitData[1],user);}else{handlerRequestFromServer(caseTitle,splitData[1],user);}}}
function handlerPotencialParticipiant(data,user){let potencialParticipiant=Object.values(data);potencialParticipiant=changeUserRole(potencialParticipiant);user.setPotencialParticipiant(potencialParticipiant);}
function handlerParamForClient(data,setUser){const jsonData=JSON.parse(data);setUser(new mainUser(jsonData));}
function handlerNotification(data,user){const jsonData=JSON.parse(data);let userParam=user.getAllParam();console.log(userParam);console.log(data);if(!notifier){console.log('handlerNotification if (!notifier)');notifier=new NotificationWorker(jsonData,userParam);}else{console.log('handlerNotification else');notifier.reloadNotifier(jsonData,userParam);}}
function handlerParamForClientPages(user){const path=window.location.pathname.replace(/^\/|\/$/g,'');const functionName='handler'+switchCommand(toCapsCase(path));if(typeof window[functionName]==='function'){window[functionName](user);}else{}}